<?php require __DIR__.'/../../bootstrap/app.php';role_required('admin');$db=Database::get();
$err=[];$f=['id'=>0,'title'=>'','sector'=>'','description'=>'','status'=>'planned'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);
 if(($_POST['action']??'')==='delete'&&$id){$db->prepare("DELETE FROM projects WHERE id=?")->execute([$id]);audit('delete project','project',$id);notice('Project deleted.');go('admin/projects.php');}
 $f=['id'=>$id,'title'=>trim((string)($_POST['title']??'')),'sector'=>trim((string)($_POST['sector']??'')),'description'=>trim((string)($_POST['description']??'')),'status'=>$_POST['status']??'planned'];
 if(mb_strlen($f['title'])<3||mb_strlen($f['title'])>180)$err[]='Title must be 3-180 characters.';if(!in_array($f['status'],['planned','ongoing','completed'],true))$err[]='Invalid status.';
 if(!$err){if($id){$db->prepare("UPDATE projects SET title=?,sector=?,description=?,status=? WHERE id=?")->execute([$f['title'],$f['sector'],$f['description'],$f['status'],$id]);audit('update project','project',$id);}else{$db->prepare("INSERT INTO projects(title,sector,description,status) VALUES(?,?,?,?)")->execute([$f['title'],$f['sector'],$f['description'],$f['status']]);audit('create project','project',(int)$db->lastInsertId());}notice('Project saved.');go('admin/projects.php');}}
elseif(isset($_GET['id'])){$s=$db->prepare("SELECT * FROM projects WHERE id=?");$s->execute([(int)$_GET['id']]);$f=$s->fetch()?:$f;}
$rows=$db->query("SELECT id,title,sector,status FROM projects ORDER BY id DESC")->fetchAll();
$title='Projects';require __DIR__.'/../../app/Views/header.php';?><section class="section"><div class="container"><div class="dash"><?php require __DIR__.'/../../app/Views/admin_nav.php';?><div><h1>Projects</h1><?php foreach($err as $m):?><div class="alert alert-danger"><?=e($m)?></div><?php endforeach;?>
<form method="post" class="cardx mb-4"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$f['id']?>"><h3><?=$f['id']?'Edit project':'Add project'?></h3><input class="form-control mb-2" name="title" placeholder="Title" required maxlength="180" value="<?=e($f['title'])?>"><input class="form-control mb-2" name="sector" placeholder="Sector" maxlength="100" value="<?=e($f['sector'])?>"><textarea class="form-control mb-2" name="description" rows="3" placeholder="Description"><?=e($f['description'])?></textarea><select class="form-select mb-2" name="status"><?php foreach(['planned','ongoing','completed'] as $s):?><option <?=$f['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-dark">Save project</button></form>
<table class="table"><tr><th>Title</th><th>Sector</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['sector'])?></td><td><?=e($r['status'])?></td><td><a href="?id=<?=(int)$r['id']?>">Edit</a> <form method="post" class="d-inline" onsubmit="return confirm('Delete this project?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-link text-danger p-0">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4">No projects yet.</td></tr><?php endif;?></table></div></div></div></section><?php require __DIR__.'/../../app/Views/footer.php';?>
